from rosterkit.errors import ProjectError


def contact_sheet(students):
    if not students:
        raise ProjectError("no students for the contact sheet")
    for student in students:
        if not student.email:
            raise ProjectError(
                f"no email for {student.display_name}"
            )
    ordered = sorted(students, key=lambda s: s.display_name)
    width = max(len(s.display_name) for s in ordered)
    section_width = max(len(s.section) for s in ordered)
    return [
        f"{s.display_name:<{width}}  "
        f"{s.section:<{section_width}}  {s.email}"
        for s in ordered
    ]
EOF
cat > qa/test_contacts.py <<'EOF'
import unittest

from rosterkit.contacts import contact_sheet
from rosterkit.errors import ProjectError
from rosterkit.models import Student


def student(last, first, section, email):
    return Student("1", last, first, section, email)


class ContactSheetTests(unittest.TestCase):
    def test_rows_are_sorted_and_aligned(self):
        rows = contact_sheet([
            student("Zed", "Amy", "B", "amy@x.org"),
            student("Li", "Jo", "A", "jo@x.org"),
        ])
        self.assertEqual(rows, [
            "Li, Jo   A  jo@x.org",
            "Zed, Amy B  amy@x.org",
        ])

    def test_missing_email_names_the_student(self):
        with self.assertRaisesRegex(ProjectError, "Li, Jo"):
            contact_sheet([student("Li", "Jo", "A", None)])

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            contact_sheet([])
EOF
